const tests = [
  'Dated baseline: reconcile the cross-asset moves against the information and expectations observable at the cutoff.',
  'Rival-friendly comparison: use a matched window, instrument or benchmark where the competing mechanism makes a different prediction.',
  'Decisive observation: seek direct evidence that separates the two mechanisms and test sensitivity to a confounder.'
];
const index = Math.max(0, Math.min(inputs.iteration, tests.length) - 1);
const plan = `Pass ${inputs.iteration}. ${tests[index]}`;
const context = inputs.text ? `${plan}\n\nPrior case to revisit\n${inputs.text}` : plan;
return { text: context, number: inputs.iteration };

const audit = JSON.parse(inputs.text);
const substantive = citation => citation.basis !== 'metadata_only' && citation.relation !== 'context';
const capturedCitation = audit.hypotheses.some(hypothesis => hypothesis.citations.some(substantive));
const recordedWebCitation = audit.web_research?.sources.some(source => source.cited) ?? false;
const blockers = audit.evidence_requests.length + audit.unresolved_questions.length;
const reasons = [];
if (audit.revision_summary !== 'ready') reasons.push('the auditor asked for more evidence');
if (blockers) reasons.push(`${blockers} blocking ${blockers === 1 ? 'entry remains' : 'entries remain'}`);
if (!capturedCitation && !recordedWebCitation) reasons.push('no substantive captured citation or provider-recorded web citation');
if (!reasons.length) return { text: `Pass ${inputs.iteration} is ready for owner review.`, number: 1 };

const clip = (text, limit) => {
  const characters = Array.from(text);
  return characters.length > limit ? `${characters.slice(0, limit - 1).join('')}…` : text;
};
const requests = audit.evidence_requests.slice(0, 2).map(({ question, source_needed, why }) =>
  `Evidence question: ${clip(question, 450)}\nSource needed: ${clip(source_needed, 450)}\nWhy: ${clip(why, 450)}`
);
const questions = audit.unresolved_questions.slice(0, 2).map(question => `Unresolved: ${clip(question, 450)}`);
const text = [
  `Pass ${inputs.iteration} needs another test because ${reasons.join(', ')}.`,
  `Provisional view and objection to recheck\n${clip(audit.conclusion, 3000)}`,
  ...requests,
  ...questions
].join('\n\n');
return { text, number: 0 };
